"""StubDroid-style library summaries and summary-aware taint analysis."""

from __future__ import annotations

import argparse
import os
from dataclasses import dataclass, field

from flowdroid_analysis import (
    AccessPath,
    AbstractValue,
    EMPTY_VALUE,
    FlowDroidAnalyzer,
    FlowDroidProgramResult,
    MethodExecutionResult,
    join_value_maps,
)
from program_model import ClassDef, Method, MethodSignature, Program, Statement, load_all_benchmarks
from soot_analysis import Scene, signature_key
from utils import Timer


@dataclass(frozen=True)
class SummaryFlow:
    source: AccessPath
    target: AccessPath


@dataclass
class LibrarySummary:
    signature: MethodSignature
    flows: list[SummaryFlow] = field(default_factory=list)

    def flow_count(self) -> int:
        return len(self.flows)


@dataclass
class SymbolicValue:
    origins: set[AccessPath] = field(default_factory=set)
    objects: set[str] = field(default_factory=set)

    def copy(self) -> "SymbolicValue":
        return SymbolicValue(origins=set(self.origins), objects=set(self.objects))

    def join(self, other: "SymbolicValue") -> "SymbolicValue":
        return SymbolicValue(origins=set(self.origins | other.origins), objects=set(self.objects | other.objects))


@dataclass
class StubDroidProgramResult:
    flow_result: FlowDroidProgramResult
    summary_count: int
    summary_flows: int
    wrapper_hits: int
    metrics: dict[str, int]

    @property
    def passed(self) -> bool:
        return self.flow_result.passed


class LibrarySummaryGenerator:
    """Infers library summaries from Jimple-like method bodies."""

    def __init__(self, scene: Scene) -> None:
        self.scene = scene

    def generate(self) -> dict[str, LibrarySummary]:
        summaries: dict[str, LibrarySummary] = {}
        changed = True
        while changed:
            changed = False
            for owner, method in self.scene.iter_methods():
                if not owner.is_library or method.body is None:
                    continue
                summary = self.generate_method_summary(owner, method, summaries)
                key = signature_key(method.signature)
                if key not in summaries or summaries[key].flows != summary.flows:
                    summaries[key] = summary
                    changed = True
        return summaries

    def generate_method_summary(
        self,
        owner: ClassDef,
        method: Method,
        known_summaries: dict[str, LibrarySummary],
    ) -> LibrarySummary:
        flows: set[SummaryFlow] = set()
        ir = self.scene.get_ir(method.signature)
        if ir is None:
            return LibrarySummary(signature=method.signature, flows=[])

        locals_state: dict[str, SymbolicValue] = {}
        heap_state: dict[tuple[str, str], set[AccessPath]] = {}

        body = method.body
        assert body is not None

        if body.this_local and not method.is_static:
            locals_state[body.this_local] = SymbolicValue(
                origins={AccessPath("this")},
                objects={"this"},
            )

        for index, param_local in enumerate(body.param_locals):
            root = f"parameter{index}"
            locals_state[param_local] = SymbolicValue(
                origins={AccessPath(root)},
                objects={root},
            )

        for stmt in ir.statements:
            explicit_flow = self._parse_explicit_summary_flow(stmt)
            if explicit_flow is not None:
                flows.add(explicit_flow)

            if stmt.kind == "identity" and stmt.lhs is not None and stmt.rhs is not None:
                if stmt.rhs == "@this":
                    locals_state.setdefault(stmt.lhs, SymbolicValue(origins={AccessPath("this")}, objects={"this"}))
                elif stmt.rhs.startswith("@parameter"):
                    index = int(stmt.rhs[len("@parameter"):])
                    root = f"parameter{index}"
                    locals_state.setdefault(stmt.lhs, SymbolicValue(origins={AccessPath(root)}, objects={root}))
            elif stmt.kind == "assign" and stmt.lhs is not None:
                locals_state[stmt.lhs] = self._eval_symbolic(stmt.rhs, locals_state).copy()
            elif stmt.kind == "new" and stmt.lhs is not None:
                locals_state[stmt.lhs] = SymbolicValue(objects={f"alloc:{stmt.stmt_id}"})
            elif stmt.kind == "field_store" and stmt.field_ref is not None:
                rhs_value = self._eval_symbolic(stmt.rhs, locals_state)
                base_value = locals_state.get(stmt.field_ref.base, SymbolicValue())
                for base_object in base_value.objects:
                    heap_state.setdefault((base_object, stmt.field_ref.field_name), set()).update(rhs_value.origins)
                    if self._is_summary_root(base_object):
                        target = AccessPath(base_object, (stmt.field_ref.field_name,))
                        for origin in rhs_value.origins:
                            if self._is_summary_access_path(origin):
                                flows.add(SummaryFlow(source=origin, target=target))
            elif stmt.kind == "field_load" and stmt.field_ref is not None and stmt.lhs is not None:
                loaded_origins: set[AccessPath] = set()
                base_value = locals_state.get(stmt.field_ref.base, SymbolicValue())
                for base_object in base_value.objects:
                    slot = (base_object, stmt.field_ref.field_name)
                    if slot not in heap_state and self._is_summary_root(base_object):
                        heap_state[slot] = {AccessPath(base_object, (stmt.field_ref.field_name,))}
                    loaded_origins.update(heap_state.get(slot, set()))
                locals_state[stmt.lhs] = SymbolicValue(origins=loaded_origins)
            elif stmt.kind == "call" and stmt.callee is not None:
                return_value = self._apply_known_summary(stmt, locals_state, heap_state, known_summaries)
                if stmt.lhs is not None:
                    locals_state[stmt.lhs] = return_value
            elif stmt.kind == "return" and stmt.rhs is not None:
                for origin in self._eval_symbolic(stmt.rhs, locals_state).origins:
                    if self._is_summary_access_path(origin):
                        flows.add(SummaryFlow(source=origin, target=AccessPath("return")))

        filtered = {
            flow
            for flow in flows
            if self._is_summary_access_path(flow.source) and self._is_summary_access_path(flow.target)
        }
        ordered = sorted(filtered, key=lambda flow: (flow.source.render(), flow.target.render()))
        return LibrarySummary(signature=method.signature, flows=ordered)

    def _apply_known_summary(
        self,
        stmt: Statement,
        locals_state: dict[str, SymbolicValue],
        heap_state: dict[tuple[str, str], set[AccessPath]],
        known_summaries: dict[str, LibrarySummary],
    ) -> SymbolicValue:
        summary = known_summaries.get(signature_key(stmt.callee))
        if summary is None:
            receiver_value = self._eval_symbolic(stmt.receiver, locals_state)
            combined = receiver_value
            for arg in stmt.args:
                combined = combined.join(self._eval_symbolic(arg, locals_state))
            return combined

        receiver_value = self._eval_symbolic(stmt.receiver, locals_state)
        arg_values = [self._eval_symbolic(arg, locals_state) for arg in stmt.args]
        return_value = SymbolicValue()
        for flow in summary.flows:
            source_value = self._resolve_summary_source(flow.source, receiver_value, arg_values, heap_state)
            if flow.target.root == "return":
                return_value = return_value.join(source_value)
            else:
                self._store_summary_target(flow.target, source_value, receiver_value, arg_values, heap_state)
        return return_value

    def _resolve_summary_source(
        self,
        access_path: AccessPath,
        receiver_value: SymbolicValue,
        arg_values: list[SymbolicValue],
        heap_state: dict[tuple[str, str], set[AccessPath]],
    ) -> SymbolicValue:
        current = self._root_value(access_path.root, receiver_value, arg_values)
        for field_name in access_path.fields:
            loaded_origins: set[AccessPath] = set()
            for object_id in current.objects:
                slot = (object_id, field_name)
                if slot not in heap_state and self._is_summary_root(object_id):
                    heap_state[slot] = {AccessPath(object_id, (field_name,))}
                loaded_origins.update(heap_state.get(slot, set()))
            current = SymbolicValue(origins=loaded_origins)
        return current

    def _store_summary_target(
        self,
        access_path: AccessPath,
        source_value: SymbolicValue,
        receiver_value: SymbolicValue,
        arg_values: list[SymbolicValue],
        heap_state: dict[tuple[str, str], set[AccessPath]],
    ) -> None:
        if not access_path.fields:
            return
        base_value = self._root_value(access_path.root, receiver_value, arg_values)
        last_field = access_path.fields[-1]
        for object_id in base_value.objects:
            heap_state.setdefault((object_id, last_field), set()).update(source_value.origins)

    def _root_value(
        self,
        root: str,
        receiver_value: SymbolicValue,
        arg_values: list[SymbolicValue],
    ) -> SymbolicValue:
        if root == "this":
            return receiver_value.copy()
        if root.startswith("parameter"):
            index = int(root[len("parameter"):])
            if index < len(arg_values):
                return arg_values[index].copy()
        return SymbolicValue()

    def _eval_symbolic(self, token: str | None, locals_state: dict[str, SymbolicValue]) -> SymbolicValue:
        if token is None:
            return SymbolicValue()
        return locals_state.get(token, SymbolicValue()).copy()

    def _parse_explicit_summary_flow(self, stmt: Statement) -> SummaryFlow | None:
        raw_flow = stmt.metadata.get("summary_flow")
        if not raw_flow:
            return None
        if "->" not in raw_flow:
            return None
        source_raw, target_raw = [part.strip() for part in raw_flow.split("->", 1)]
        return SummaryFlow(source=self._parse_summary_access_path(source_raw), target=self._parse_summary_access_path(target_raw))

    def _parse_summary_access_path(self, raw: str) -> AccessPath:
        if raw == "return":
            return AccessPath("return")
        parts = raw.split(".")
        return AccessPath(parts[0], tuple(parts[1:]))

    def _is_summary_root(self, root: str) -> bool:
        return root == "this" or root.startswith("parameter")

    def _is_summary_access_path(self, access_path: AccessPath) -> bool:
        return access_path.root == "return" or self._is_summary_root(access_path.root)


class SummaryTaintWrapper:
    """Applies generated library summaries during taint analysis."""

    def __init__(self, summaries: dict[str, LibrarySummary]) -> None:
        self.summaries = summaries
        self.wrapper_hits = 0

    def apply(
        self,
        analyzer: "StubDroidAnalyzer",
        caller_sig: MethodSignature,
        stmt: Statement,
        target_sig: MethodSignature,
        receiver_value: AbstractValue,
        arg_values: list[AbstractValue],
        heap_in: dict[tuple[str, str], AbstractValue],
        call_stack: tuple[str, ...],
    ) -> MethodExecutionResult | None:
        summary = self.summaries.get(signature_key(target_sig))
        if summary is None:
            return None

        self.wrapper_hits += 1
        heap_out = dict(heap_in)
        return_value = EMPTY_VALUE

        for flow in summary.flows:
            source_value = self._resolve_source(flow.source, receiver_value, arg_values, heap_out)
            if flow.target.root == "return":
                return_value = return_value.join(source_value)
            else:
                heap_out = self._apply_target(analyzer, stmt, target_sig, flow.target, source_value, receiver_value, arg_values, heap_out)

        return MethodExecutionResult(return_value=return_value, heap=heap_out, leaks=frozenset())

    def _resolve_source(
        self,
        access_path: AccessPath,
        receiver_value: AbstractValue,
        arg_values: list[AbstractValue],
        heap: dict[tuple[str, str], AbstractValue],
    ) -> AbstractValue:
        current = self._root_value(access_path.root, receiver_value, arg_values)
        for field_name in access_path.fields:
            loaded = EMPTY_VALUE
            for object_id in current.objects:
                loaded = loaded.join(heap.get((object_id, field_name), EMPTY_VALUE))
            current = loaded
        return current

    def _apply_target(
        self,
        analyzer: "StubDroidAnalyzer",
        stmt: Statement,
        target_sig: MethodSignature,
        access_path: AccessPath,
        source_value: AbstractValue,
        receiver_value: AbstractValue,
        arg_values: list[AbstractValue],
        heap: dict[tuple[str, str], AbstractValue],
    ) -> dict[tuple[str, str], AbstractValue]:
        if not access_path.fields:
            return heap

        base_value = self._root_value(access_path.root, receiver_value, arg_values)
        last_field = access_path.fields[-1]
        rebound = analyzer._rebind_value(  # noqa: SLF001 - reused analysis primitive
            source_value,
            access_path=AccessPath(stmt.receiver or access_path.root).extend(last_field),
            label=analyzer._field_label(  # noqa: SLF001 - reused analysis primitive
                stmt.receiver or access_path.root,
                last_field,
                note=f"via {target_sig.method_name}",
            ),
        )

        heap_out = dict(heap)
        for object_id in base_value.objects:
            slot = (object_id, last_field)
            heap_out[slot] = heap_out.get(slot, EMPTY_VALUE).join(rebound)
        return heap_out

    def _root_value(
        self,
        root: str,
        receiver_value: AbstractValue,
        arg_values: list[AbstractValue],
    ) -> AbstractValue:
        if root == "this":
            return receiver_value
        if root.startswith("parameter"):
            index = int(root[len("parameter"):])
            if index < len(arg_values):
                return arg_values[index]
        return EMPTY_VALUE


class StubDroidAnalyzer(FlowDroidAnalyzer):
    """Summary-aware FlowDroid variant."""

    def __init__(self, program: Program) -> None:
        super().__init__(program)
        self.summary_generator = LibrarySummaryGenerator(self.scene)
        self.summaries = self.summary_generator.generate()
        self.taint_wrapper = SummaryTaintWrapper(self.summaries)

    def should_inline_body(self, target_owner: ClassDef, target_method: Method) -> bool:
        if target_owner.is_library and signature_key(target_method.signature) in self.summaries:
            return False
        return True

    def apply_taint_wrapper(
        self,
        caller_sig: MethodSignature,
        stmt: Statement,
        target_sig: MethodSignature,
        receiver_value: AbstractValue,
        arg_values: list[AbstractValue],
        heap_in: dict[tuple[str, str], AbstractValue],
        call_stack: tuple[str, ...],
    ) -> MethodExecutionResult | None:
        return self.taint_wrapper.apply(
            analyzer=self,
            caller_sig=caller_sig,
            stmt=stmt,
            target_sig=target_sig,
            receiver_value=receiver_value,
            arg_values=arg_values,
            heap_in=heap_in,
            call_stack=call_stack,
        )

    def analyze(self) -> StubDroidProgramResult:
        flow_result = super().analyze()
        metrics = dict(flow_result.metrics)
        metrics["summary_count"] = len(self.summaries)
        metrics["summary_flows"] = sum(summary.flow_count() for summary in self.summaries.values())
        metrics["wrapper_hits"] = self.taint_wrapper.wrapper_hits
        return StubDroidProgramResult(
            flow_result=flow_result,
            summary_count=metrics["summary_count"],
            summary_flows=metrics["summary_flows"],
            wrapper_hits=metrics["wrapper_hits"],
            metrics=metrics,
        )


def analyze_program(program: Program) -> StubDroidProgramResult:
    return StubDroidAnalyzer(program).analyze()


def analyze_benchmarks(directory: str) -> list[StubDroidProgramResult]:
    return [analyze_program(program) for program in load_all_benchmarks(directory)]


def summarize_results(results: list[StubDroidProgramResult], runtime_ms: float) -> dict[str, str]:
    benchmark_count = len(results)
    passed = sum(1 for result in results if result.passed)
    summary_count = sum(result.summary_count for result in results)
    summary_flows = sum(result.summary_flows for result in results)
    wrapper_hits = sum(result.wrapper_hits for result in results)
    expected_leaks = sum(result.metrics["expected_leaks"] for result in results)
    detected_leaks = sum(result.metrics["detected_leaks"] for result in results)
    missing_leaks = sum(result.metrics["missing_leaks"] for result in results)
    unexpected_leaks = sum(result.metrics["unexpected_leaks"] for result in results)

    status = "OK" if passed == benchmark_count else "MISMATCH"
    return {
        "STUBDROID_STATUS": status,
        "STUBDROID_BENCHMARKS": str(benchmark_count),
        "STUBDROID_BENCHMARKS_PASSED": f"{passed}/{benchmark_count}",
        "STUBDROID_SUMMARIES": str(summary_count),
        "STUBDROID_SUMMARY_FLOWS": str(summary_flows),
        "STUBDROID_WRAPPER_HITS": str(wrapper_hits),
        "STUBDROID_EXPECTED_LEAKS": str(expected_leaks),
        "STUBDROID_DETECTED_LEAKS": str(detected_leaks),
        "STUBDROID_MISSING_LEAKS": str(missing_leaks),
        "STUBDROID_UNEXPECTED_LEAKS": str(unexpected_leaks),
        "STUBDROID_RUNTIME_MS": f"{runtime_ms:.3f}",
    }


def emit_metrics(metrics: dict[str, str]) -> None:
    for key, value in metrics.items():
        print(f"{key}: {value}")


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--benchmarks",
        default=os.path.join(os.path.dirname(__file__), "benchmarks"),
        help="Directory containing benchmark JSON files.",
    )
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    with Timer() as timer:
        results = analyze_benchmarks(args.benchmarks)
    metrics = summarize_results(results, timer.elapsed_ms)
    emit_metrics(metrics)
    return 0 if metrics["STUBDROID_STATUS"] == "OK" else 1


if __name__ == "__main__":
    raise SystemExit(main())
